Translate the following GNU C++0x code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++0x code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

using vi = vector<int>;
using ll = long long;

const int INF = 1000000007;

template<typename T>
void input(T& x) { scanf("%d", &x); }

template<typename T, typename... Args>
void input(T& first, Args&... rest) {
    scanf("%d", &first);
    input(rest...);
}

template<typename T>
void input_vector(T& v, int n) {
    v.resize(n);
    for (int i = 0; i < n; ++i) {
        input(v[i]);
    }
}

template<typename T>
void output(T x) { printf("%d", x); }

template<typename T>
void output_line(T x) { printf("%d\n", x); }

template<typename T>
void output_vector(const T& v) {
    for (size_t i = 0; i < v.size(); ++i) {
        printf("%d%c", v[i], (i == v.size() - 1) ? '\n' : ' ');
    }
}

void process() {
    int n, t;
    vi data;
    input(n);
    input_vector(data, n);
    sort(data.begin(), data.end());

    int left = 0, right = 0, best = 0;
    input(t);

    while (right < n) {
        while (right < n && data[right] - data[left] <= t) {
            ++right;
        }
        best = max(best, right - left);
        ++left;
    }

    output_line(best);
}

int main() {
    process();
    return 0;
}
